function countLetters(s) {
  let total = 0;
  let runStart = 0;

  for (let i = 1; i <= s.length; i++) {
    if (i === s.length || s[i] !== s[runStart]) {
      const length = i - runStart;
      total += (length * (length + 1)) / 2;
      runStart = i;
    }
  }
  return total;
}

