function countLetters(s) {
  let count = 0;
  for (let i = 0; i < s.length; i++) {
    let same = true;
    for (let j = i; j < s.length; j++) {
      same = same && s[j] === s[i];
      if (same) count++;
    }
  }
  return count;
}

