function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  if (size === 'small') {
    const kinds = int(1, 3);
    return [Array.from({ length: int(1, 10) }, () => letters[int(0, kinds - 1)]).join('')];
  }
  // Runs of random lengths, so long runs and single letters both appear.
  const longest = [1, 5, 60, 400][int(0, 3)];
  let s = '';
  while (s.length < 1000) {
    const letter = letters[int(0, 25)];
    s += letter.repeat(int(1, longest));
  }
  return [s.slice(0, 1000)];
}
